#!/usr/bin/env python3
"""Generate metadata, never behavior, for Fear No Evil and Shadowland."""
import json,re,importlib.util,sys
sys.dont_write_bytecode = True
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
spec=importlib.util.spec_from_file_location('cw',ROOT/'tools/generate-civil-war-definitions.py');cw=importlib.util.module_from_spec(spec);spec.loader.exec_module(cw)
cw.TRAITS['Hand']='TheHand'
cards=[c for c in json.loads((ROOT/'frontend/public/data/cards.json').read_text())['cards'] if c.get('packCode') in ['fne','shadowland'] and c.get('faction')=='encounter' and (c['packCode']=='shadowland' or int(c['code'][:5])>=60065)]
overrides=json.loads((ROOT/'data/card-text/street-encounter-stats.json').read_text())
for c in cards:c.update(overrides.get(c['code'],{}))
sets={c['setCode']:('Sl' if c['packCode']=='shadowland' else 'Fne')+cw.constructor(c['setCode'].removeprefix('shadowland-')) for c in cards}
p=ROOT/'src/Marvel/EncounterSet.hs';s=p.read_text();marker='  = CwAtlanteans';s=s.replace(marker,'  = '+ '\n  | '.join(sets.values())+'\n  | CwAtlanteans') if 'FneBullseye' not in s else s;p.write_text(s)
traits={cw.trait(t) for c in cards for t in c.get('traits',[])}
p=ROOT/'src/Marvel/Trait/Types.hs';s=p.read_text();missing=sorted(t for t in traits if not re.search(r'\b'+t+r'\b',s));s=s.replace('  = Unregistered','  = '+'\n  | '.join(missing)+'\n  | Unregistered') if missing else s;p.write_text(s)
for pack,mod in [('fne','FearNoEvil'),('shadowland','Shadowland')]:
 cs=[c for c in cards if c['packCode']==pack];out=['-- Generated by tools/generate-street-encounter-definitions.py.','module Marvel.'+mod+'.Cards where','','import Marvel.Prelude','import Marvel.Card','import Marvel.Hood.Cards (hoodCardDef)','import Marvel.EncounterSet qualified as Set','import Marvel.Trait qualified as T','import Marvel.Keyword qualified as K','import Marvel.GameValue.Types qualified as GV','import Marvel.Boost qualified as B','']
 if mod=='FearNoEvil':out.insert(3,'import Marvel.Aspect qualified as Aspect')
 for c in cs:
  qty=c.get('quantity',1) if c['type'] not in ['main_scheme','villain','ally','support','upgrade'] and not c.get('linkedTo') else 0
  if c['code'] in ['60139','60169']:qty=c.get('quantity',1)
  # Linked encounter cards are included only by scenario setup, not by gathering their set.
  if c['setCode']=='shadowland-dark-protege':qty=0
  keyword_card=dict(c)
  keyword_card['text']=re.sub(r'^Linked\s*\([^)]*\)\.\s*', '', re.sub(r'^\[star\]\s*', '', re.sub(r'<[^>]*>', '',c.get('text',''))))
  kw=cw.keywords(keyword_card)
  kw=[k.replace('T.','T.') for k in kw]
  text=re.sub('<[^>]*>','',c.get('text',''))
  for k in ['Assault','Vulnerable','Setup']:
   if re.search(r'\b'+k+r'\.',text.split('[star] Boost')[0]) and 'K.'+k not in kw:kw.append('K.'+k)
  if c['code'] in ['60210a','60210b']:kw.append('K.Victory (-1)')
  boost=c.get('boost',0);star=c.get('boostStar',False) or '[star] Boost' in text
  out += ['street'+c['code']+' :: CardDef','street'+c['code']+' = (hoodCardDef '+cw.quote(c['code'])+' '+cw.quote(c['name'])+' Set.'+sets[c['setCode']]+' '+cw.constructor(c['type'])+'Type '+str(qty)+')','  { cdTraits = fromList ['+', '.join('T.'+cw.trait(t) for t in c.get('traits',[]))+']', '  , cdUnique = '+str(c.get('unique',False)), '  , cdKeywords = fromList ['+', '.join(kw)+']','  , cdBoostIcons = ['+', '.join(['B.Boost']*boost+['B.Star']*bool(star))+']','  , cdHazards = '+str(c.get('hazard',0))+', cdAcceleration = '+str(c.get('acceleration',0))+', cdAmplify = '+str(c.get('amplify',0)), '  , cdAlternateCardCodes = ['+(cw.quote(c['linkedTo']) if c.get('linkedTo') else '')+']','  }','']
  if c['code'] in ['60210a','60210b']:out.insert(len(out)-2,'  , cdAspect = Just Aspect.'+('Justice' if c['code']=='60210a' else 'Aggression'))
 out+=['streetDefinitions :: [CardDef]','streetDefinitions = ['+', '.join('street'+c['code'] for c in cs)+']','']
 p=ROOT/'src/Marvel'/mod/'Cards.hs';p.parent.mkdir(exist_ok=True);p.write_text('\n'.join(out) if any('GV.' in line for line in out) else '\n'.join(line for line in out if 'import Marvel.GameValue.Types' not in line))
# Beetle names a particular host, so RR Attach To says not to resolve the chosen
# attachment's normal host-selection instruction. Its eligible target class still
# has to include minions; exclude identity-, ally-, scheme-, and leader-only cards.
index=json.loads((ROOT/'frontend/public/data/cards.json').read_text())['cards']
attachable=[]
for c in index:
 if c.get('type')!='attachment':continue
 text=re.sub(r'<[^>]*>','',c.get('text','')).replace('\\n','\n')
 phrase=re.search(r'attach (?:this card )?to ([^\n.]+)',text,re.I)
 if phrase and re.search(r'\bminion\b|\benemy\b(?!\s+(?:leader|team))',phrase[1],re.I):attachable.append(c['code'])
p=ROOT/'src/Marvel/Attachment/MinionEligibility.hs'
p.write_text('-- Generated from the local card text by tools/generate-street-encounter-definitions.py.\nmodule Marvel.Attachment.MinionEligibility (minionAttachment) where\n\nimport Marvel.Prelude\nimport Marvel.Card\n\nminionAttachment :: CardDef -> Bool\nminionAttachment def = toCardCode def `elem` ['+', '.join(cw.quote(code) for code in attachable)+']\n')
